import{_ as o,l as r,o as a,c as p,v as l,p as s,x as i,d as n,i as E,S as c}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"薄膜安装与检验","description":"","frontmatter":{"title":"薄膜安装与检验","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/pellicle-mount-inspect.md","filePath":"litho/pellicle-mount-inspect.md","lastUpdated":1789023840000}'),h={name:"litho/pellicle-mount-inspect.md"};function d(m,e,_,A,u,B){const t=r("Mermaid");return a(),p("div",null,[e[1]||(e[1]=l('<h1 id="薄膜安装与检验" tabindex="-1">薄膜安装与检验 <a class="header-anchor" href="#薄膜安装与检验" aria-label="Permalink to &quot;薄膜安装与检验&quot;">​</a></h1><div class="epigraph"><p>Pellicle 把颗粒移到离焦面；安装本身引入框架应力、密封与透过率指纹，必须当作掩模的最后一道图形化。</p><footer>—— 对照 DUV pellicle 安装惯例；EUV 膜见 ASML pellicle 公开材料与 Bakshi</footer></div><p><a href="/litho/mask-repair-ebeam">上一课</a>把可修缺陷补完。缺口是上机前还要罩膜：DUV 有机膜成熟，EUV 膜是另一份热与透过合同。本课钉安装与检验。装好后如何用空中像鉴定打印，留给[下一课](/litho/aims-mask-qualification）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/euv-pellicle">EUV pellicle</a> 已讲膜的光学与热。本课站在掩模厂：框架对准有效区、胶粘或机械固定、气密、膜皱与颗粒、安装后复检。DUV 膜透过率高、热负荷低，主要风险是破膜、胶挥发污染与安装颗粒。EUV 膜透过率进入剂量，皱与热鼓包进入全场 CD——安装站是这张指纹的源头之一。</p><p>缺口是<strong>机械合同</strong>，不是再推导双程透过率。把 pellicle 当「配件」，会漏掉：装完再修缺陷往往要拆膜，周期翻倍。</p><h3 id="无膜运行是另一种安装决策" tabindex="-1">无膜运行是另一种安装决策 <a class="header-anchor" href="#无膜运行是另一种安装决策" aria-label="Permalink to &quot;无膜运行是另一种安装决策&quot;">​</a></h3><p>EUV 曾有无 pellicle 跑关键层的阶段：检验频率与报废率换掉膜风险。那是 fab 策略，仍要在本课登记：无膜则安装检验变成「裸版颗粒图 + 搬运协议」。</p><p><span class="marginnote">框架挡掉一圈有效区。MDP 作业框必须与可安装 pellicle 的窗口一致，否则条码或阵列被框遮住。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>安装后：颗粒检验（膜上与膜下，光学条件不同）、透过率/均匀性（EUV 更关键）、密封、外观皱纹。DUV 可用专用 pellicle 检验机；EUV 还要考虑膜在真空与氢环境的后续寿命——寿命课已有，本课只把「安装合格」定义为上机起点。</p><p>与配准：框架应力可轻微弯版，配准与焦面要在安装后再抽检，不能只用未装膜数据出货。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>膜在离焦面，颗粒的打印阈值大幅提高；膜自身的厚度与折射率不均匀是在焦光束里的弱相位/吸收物体，会留下缓慢 CD 指纹。安装张力不均 → 皱 → 局部角与透过变化。EUV 双程放大这份不均匀。扫描热使膜鼓包随时间变，OPC 吃不掉时变项。</p>',14)),(a(),s(c,null,{default:i(()=>[E(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20REP%5B%22%E4%BF%AE%E5%A4%8D%E5%90%8E%E8%A3%B8%E7%89%88%22%5D%20--%3E%20MNT%5B%22%E6%A1%86%E6%9E%B6%20%2B%20%E8%86%9C%E5%AE%89%E8%A3%85%22%5D%0A%20%20MNT%20--%3E%20INSP%5B%22%E8%86%9C%E4%B8%8A%E9%A2%97%E7%B2%92%20%2F%20%E9%80%8F%E8%BF%87%20%2F%20%E7%9A%B1%22%5D%0A%20%20INSP%20--%3E%20STRESS%5B%22%E5%BA%94%E5%8A%9B%20%E2%86%92%20%E9%9D%A2%E5%BD%A2%22%5D%0A%20%20STRESS%20--%3E%20AIMS%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E6%89%93%E5%8D%B0%E9%89%B4%E5%AE%9A%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>安装不消除空白多层缺陷。破膜率与寿命不在本课用数字承诺。不把 DUV 有机膜的安装扭矩抄到 EUV CNT/SiN 膜上。</p><p>后课默认：出货状态含 pellicle（或明确无膜协议）；下一课用 AIMS 问「这块版在扫描机波长下怎么印」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Pellicle 安装是最后一道会改指纹的工序：应力、透过、颗粒。</li><li>有效区与框架必须在 MDP 阶段就对齐。</li><li>装膜后配准/焦面可能变化，需复测。</li><li>出处：DUV pellicle 安装惯例；EUV pellicle 公开材料与 Bakshi 膜讨论。</li></ul>',5))])}const V=o(h,[["render",d]]);export{D as __pageData,V as default};
